(46, 31, 'TV LCD·LED 패널 불량 진단', '백라이트 점멸 진단, 패널 수직선·암점 원인 분석, T-CON 교체 절차를 학습합니다.', NULL, 'INTERMEDIATE', 'TEXT', '1.1', 1, 2, '2024-03-01 09:00:00', '2025-01-05 09:00:00'),
(47, 31, 'TV SMPS 및 메인보드 고급 진단', 'SMPS 전압 측정·교체, 메인보드 에러코드 분석, 패널 교체 비용 산정을 심화 학습합니다.', NULL, 'ADVANCED', 'TEXT', '1.0', 1, 3, '2024-03-01 09:00:00', '2025-01-05 09:00:00'),
(48, 31, 'TV 공통 고객 응대 가이드', '수리 완료 후 화질 점검, 고객 서명 수령, 수리 불가 판정 안내 절차를 안내합니다.', NULL, 'ALL', 'TEXT', '1.0', 1, 1, '2024-03-15 09:00:00', '2025-01-05 09:00:00'),
(74, 31, '디스플레이 내부 구조에 대한 이해', NULL, 'https://www.youtube.com/watch?v=Gx-JVoOFYhs', 'BEGINNER', 'VIDEO', '1.0', 1, 1, '2026-01-01 09:00:00', '2026-01-01 09:00:00'),
(75, 31, 'LCD 및 LED 패널에 대한 이해', NULL, 'https://www.youtube.com/watch?v=izd7dhtmZjc', 'INTERMEDIATE', 'VIDEO', '1.0', 1, 1, '2026-01-01 09:00:00', '2026-01-01 09:00:00'),
