(49, 32, '빔프로젝터 기초 광학 및 램프 점검', '투사 광학계 원리, 램프 수명 확인, 기초 초점·키스톤 조정을 학습합니다.', NULL, 'BEGINNER', 'TEXT', '1.0', 1, 2, '2024-04-01 09:00:00', '2025-01-05 09:00:00'),
(50, 32, '빔프로젝터 컬러휠 및 DMD 진단', '컬러휠 파손 진단, DMD 미러 오염 청소, 광원 PCB 불량 판별을 학습합니다.', NULL, 'INTERMEDIATE', 'TEXT', '1.0', 1, 2, '2024-04-01 09:00:00', '2025-01-05 09:00:00'),
(51, 32, '빔프로젝터 레이저 광원 고급 진단', '레이저 모듈 교체, 광량 보정, 고급 광학 정렬 절차를 심화 학습합니다.', NULL, 'ADVANCED', 'TEXT', '1.0', 1, 3, '2024-04-01 09:00:00', '2025-01-05 09:00:00'),
(52, 32, '빔프로젝터 공통 고객 응대 가이드', '설치 환경 권고, 램프 교체 주기 안내, 수리 완료 후 투사 테스트를 안내합니다.', NULL, 'ALL', 'TEXT', '1.0', 1, 1, '2024-04-15 09:00:00', '2025-01-05 09:00:00'),
(53, 41, '사운드바 기초 음향 및 연결 점검', 'HDMI ARC·광케이블 연결, 기초 음향 설정, 파손 유닛 육안 점검을 학습합니다.', NULL, 'BEGINNER', 'TEXT', '1.0', 1, 1, '2024-04-10 09:00:00', '2025-01-05 09:00:00'),
(54, 41, '사운드바 앰프 기판 및 유닛 진단', '클래스D 앰프 PCB 진단, 드라이버 유닛 임피던스 측정, 무선 연결 오류 해결을 학습합니다.', NULL, 'INTERMEDIATE', 'TEXT', '1.0', 1, 2, '2024-04-10 09:00:00', '2025-01-05 09:00:00'),
(55, 41, '사운드바 DSP 및 고급 음향 보정', 'DSP 펌웨어 업데이트, 자동 음장 보정, 앰프 보드 교체 절차를 심화 학습합니다.', NULL, 'ADVANCED', 'TEXT', '1.0', 1, 2, '2024-04-10 09:00:00', '2025-01-05 09:00:00'),
(56, 41, '사운드바 공통 고객 응대 가이드', 'TV 연동 설정 안내, 볼륨 이상 증상 상담, 수리 완료 후 청음 테스트를 안내합니다.', NULL, 'ALL', 'TEXT', '1.0', 1, 1, '2024-04-25 09:00:00', '2025-01-05 09:00:00'),
(57, 42, '홈시어터 기초 채널 설정 및 점검', '5.1·7.1 채널 구성, 스피커 배선 점검, 기초 앰프 설정을 학습합니다.', NULL, 'BEGINNER', 'TEXT', '1.0', 1, 1, '2024-04-10 09:00:00', '2025-01-05 09:00:00'),
(58, 42, '홈시어터 앰프 리시버 및 디코더 진단', '앰프 리시버 PCB 진단, Dolby·DTS 디코더 오류 분석, HDMI 매트릭스 점검을 학습합니다.', NULL, 'INTERMEDIATE', 'TEXT', '1.0', 1, 2, '2024-04-10 09:00:00', '2025-01-05 09:00:00'),
(59, 42, '홈시어터 리시버 교체 및 룸 보정', '리시버 보드 교체, Audyssey·MCACC 자동 보정, 스피커 딜레이 재조정을 심화 학습합니다.', NULL, 'ADVANCED', 'TEXT', '1.0', 1, 2, '2024-04-10 09:00:00', '2025-01-05 09:00:00'),
(60, 42, '홈시어터 공통 고객 응대 가이드', '설치 환경 권고, 채널 배치 안내, 수리 완료 후 멀티채널 테스트를 안내합니다.', NULL, 'ALL', 'TEXT', '1.0', 1, 1, '2024-04-25 09:00:00', '2025-01-05 09:00:00'),
(61, 43, '스피커 기초 드라이버 및 인클로저 이해', '우퍼·트위터·미드레인지 역할, 인클로저 설계, 임피던스 기초 측정을 학습합니다.', NULL, 'BEGINNER', 'TEXT', '1.0', 1, 1, '2024-04-10 09:00:00', '2025-01-05 09:00:00'),
(62, 43, '스피커 드라이버 유닛 및 크로스오버 진단', '드라이버 단선·코일 진단, 크로스오버 네트워크 커패시터 불량 판별을 학습합니다.', NULL, 'INTERMEDIATE', 'TEXT', '1.0', 1, 2, '2024-04-10 09:00:00', '2025-01-05 09:00:00'),
(63, 43, '스피커 드라이버 교체 및 주파수 보정', '드라이버 유닛 교체 후 주파수 응답 측정, 크로스오버 재조정, 시간 정렬 설정을 심화 학습합니다.', NULL, 'ADVANCED', 'TEXT', '1.0', 1, 2, '2024-04-10 09:00:00', '2025-01-05 09:00:00'),
